pub fn survivor_mesh(node: SurvivorNode) -> Option<MeshBuffer> {
    let triangles = match node {
        SurvivorNode::Pelvis => PELVIS,
        SurvivorNode::Torso => TORSO,
        SurvivorNode::Head => HEAD,
        SurvivorNode::UpperArmL => UPPER_ARM_L,
        SurvivorNode::ForearmL => FOREARM_L,
        SurvivorNode::HandL => HAND_L,
        SurvivorNode::ThighL => THIGH_L,
        SurvivorNode::ShinL => SHIN_L,
        SurvivorNode::FootL => FOOT_L,
        SurvivorNode::UpperArmR => UPPER_ARM_R,
        SurvivorNode::ForearmR => FOREARM_R,
        SurvivorNode::HandR => HAND_R,
        SurvivorNode::ThighR => THIGH_R,
        SurvivorNode::ShinR => SHIN_R,
        SurvivorNode::FootR => FOOT_R,
        _ => return None,
    };
    let meta = VertexMeta::DEFAULT.with_tag(GeometryTag::Actor)
        .with_flags(MaterialFlags::ACTOR_MIN_LIGHT | MaterialFlags::CUTAWAY_EXEMPT);
    let mut b = MeshBuilder::new();
    for &(points, color) in triangles {
        let [a, c, d] = points.map(Vec3::from_array);
        b.push_triangle(a, c, d, WorldVertex::rgba8(color[0], color[1], color[2], 255), meta);
    }
    Some(b.build())
}
